def count_vowels(s):
    # Dictionary to store counts of vowels
    vowel_counts = {'a': 0, 'e': 0, 'i': 0, 'o': 0, 'u': 0}

    # Convert the string to lowercase to make the search case-insensitive
    s = s.lower()

    # Count the number of each vowel in the string
    for char in s:
        if char in vowel_counts:
            vowel_counts[char] += 1

    # Return the sum of the counts of all vowels
    return sum(vowel_counts.values())
