def count_vowels(s, memo=None):
    if memo is None:
        memo = {}

    if s in memo:
        return memo[s]
    else:
        length = len(s)
        if length == 0:
            return 0
        res = 0
        for i in range(length):
            if s[i] in vowels:
                res += 1
        memo[s] = res
        return res
